from openpyxl import load_workbook

wb = load_workbook("budget.xlsx", data_only=True)
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (dims {ws.dimensions}) ===")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {cell.value!r}")

import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(col):
    idx = 0
    for ch in col:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

def cell_ref_to_rc(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    return col_to_idx(m.group(1)), int(m.group(2)) - 1

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("Archive entries:", names)

    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            shared.append("".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")))

    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))
              for s in wb_root.find("m:sheets", NS)]
    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels_root}

    for sheet_name, rid in sheets:
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        print(f"\n=== Sheet: {sheet_name} ({target}) ===")
        sroot = ET.fromstring(z.read(target))
        for row in sroot.iter("m:row", NS):
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                if v is None:
                    continue
                val = v.text
                if t == "s":
                    val = shared[int(val)]
                elif t == "b":
                    val = val == "1"
                elif t == "inlineStr":
                    is_ = c.find("m:is", NS)
                    val = "".join(x.text or "" for x in is_.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                print(f"{ref}: {val!r}")

